// devices.platform.syncDevices — E4, D-29. Generated by `pnpm gen:command`; guard cases kept, acceptance cases
// added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import {
  aStaffActor,
  countRows,
  createFakeClock,
  createTestDatabase,
  runAsOwner,
  type TestDatabase,
} from '@ocs/testing';
import {
  Conflict,
  Forbidden,
  NotFound,
  openTestKernel,
  systemActor,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { registerDevice } from '../commands/register-device.ts';
import { syncDevices } from '../commands/sync-devices.ts';

const sync = systemActor('device-platform');
const pm = aStaffActor({ roles: ['pm'] });
const clock = createFakeClock(new Date('2026-11-03T10:00:00Z'));
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
let siteB: string;
const rows = (from: string, params: unknown[] = []) => countRows(testDb.url, from, params);
const events = (type: string) => rows('outbox WHERE event_type = $1', [type]);
const run = (input: Record<string, unknown>) =>
  t.kernel.execute(syncDevices, sync, { siteId: siteA, ...input }, 'system');

const devices = [
  { sn: 'SN-0001', model: 'G6-8MA', mac: 'aa-bb-cc-00-00-01', ip: '10.0.0.21', status: 'online' },
  { sn: 'SN-0002', model: 'G6-8MA', status: 'offline' },
];

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url, { clock: clock.now });
  const setup = aStaffActor({ roles: ['director'] });
  t.grant(setup, createClient.permission, createSite.permission);
  t.grant(sync, syncDevices.permission);
  t.grant(pm, registerDevice.permission);
  const a = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
  const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', name: 'Mall A', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  ({ id: siteB } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  // No command links a project to its mall yet (next slice); set it up directly.
  await runAsOwner(testDb.url, `UPDATE site SET platform_ref = 'mall-a' WHERE id = $1`, [siteA]);
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('devices.platform.syncDevices', () => {
  it('refuses anyone but the system actor, a bad snapshot, and a project without a mall', async () => {
    await expect(
      t.kernel.execute(syncDevices, pm, { siteId: siteA, devices: [] }, 'test'),
    ).rejects.toBeInstanceOf(Forbidden);
    for (const bad of [[devices[0], { ...devices[1], sn: 'sn-0001' }], [{ ...devices[0], status: 'lost' }]]) {
      await expect(run({ devices: bad })).rejects.toBeInstanceOf(ValidationFailed);
    }
    await expect(run({ siteId: randomUUID(), devices: [] })).rejects.toBeInstanceOf(NotFound);
    await expect(run({ siteId: siteB, devices: [] })).rejects.toBeInstanceOf(Conflict);
    expect(await rows('audit_event WHERE command = $1', [syncDevices.name])).toBe(0);
  });

  it('first sync adds the devices; one seen offline gets offline_since and a went_offline event', async () => {
    expect(await run({ devices })).toEqual({ added: 2, updated: 0, elsewhere: [], offlineEnded: [] });
    expect(
      await rows(
        `device WHERE sn = 'SN-0001' AND mac = 'AA:BB:CC:00:00:01' AND status = 'installed' AND platform_status = 'online'`,
      ),
    ).toBe(1);
    expect(await rows(`device WHERE sn = 'SN-0002' AND offline_since = $1`, [clock.now()])).toBe(1);
    expect(await events('devices.device.went_offline')).toBe(1);
    expect(await rows('audit_event WHERE command = $1', [syncDevices.name])).toBe(1);
  });

  it('the same snapshot again changes nothing and raises no event (idempotent)', async () => {
    clock.advance({ minutes: 15 });
    expect(await run({ devices })).toEqual({ added: 0, updated: 0, elsewhere: [], offlineEnded: [] });
    expect(await rows(`device WHERE sn = 'SN-0002' AND offline_since < synced_at`)).toBe(1);
    expect(await events('devices.device.went_offline')).toBe(1);
  });

  it('a new MAC after restart and status changes are taken from the platform (D-29)', async () => {
    clock.advance({ minutes: 15 });
    const r = await run({
      devices: [
        { ...devices[0], mac: 'AA:BB:CC:00:00:99', status: 'offline' },
        { ...devices[1], status: 'online' },
      ],
    });
    expect(r.updated).toBe(2);
    expect(r.offlineEnded).toEqual([
      { deviceId: expect.any(String) as string, sn: 'SN-0002', offlineSince: '2026-11-03T10:00:00.000Z' },
    ]);
    expect(
      await rows(`device WHERE sn = 'SN-0001' AND mac = 'AA:BB:CC:00:00:99' AND offline_since = $1`, [
        clock.now(),
      ]),
    ).toBe(1);
    expect(
      await rows(`device WHERE sn = 'SN-0002' AND platform_status = 'online' AND offline_since IS NULL`),
    ).toBe(1);
    expect(await events('devices.device.went_offline')).toBe(2);
    expect(await events('devices.device.offline_ended')).toBe(1);
  });

  it('an SN active on another project is reported, not moved; devices the platform omits stay', async () => {
    await t.kernel.execute(registerDevice, pm, { siteId: siteB, sn: 'SN-0009', model: 'G6' }, 'test');
    const r = await run({ devices: [{ sn: 'sn-0009', model: 'G6', status: 'online' }] });
    expect([r.added, r.updated]).toEqual([0, 0]);
    expect(r.elsewhere.map((e) => [e.sn, e.projectId.endsWith('-002')])).toEqual([['sn-0009', true]]);
    expect(await rows(`device WHERE sn = 'SN-0009' AND site_id = $1`, [siteB])).toBe(1);
    expect(await rows(`device WHERE site_id = $1 AND archived_at IS NULL`, [siteA])).toBe(2);
  });
});
